# Code generated by Claude
"""One arm's inverse kinematics with mink: move the pad centre of the gripper along a pose path, level, away from the furniture.

    arm = MinkArm(model, data, "left", home_q)
    q_cmd = arm.step(data, pad_position, pad_rotation)       # one tick: the next joint command toward that pad pose
    p, R = arm.pad_pose(data)                                # the pad centre now, from the measured joints

mink runs on the full model, with every degree of freedom except the arm's 7 joints frozen (DofFreezingTask as a constraint: the rest of the
robot, the beaker and the right arm stay where `data` has them). The target is the pad centre (src/gripper_geometry.py: derived from the model),
reached through the tool point body: the frame task asks for the tool point pose that puts the pad centre at the wanted pose.

Tasks and limits (MINK_CFG in src/task_config.py): a frame task on the tool point (position and orientation), a weak posture task toward the
home pose on the arm's joints (it only chooses the elbow), the joint limits with a margin, a joint speed limit, and collision avoidance of the
left arm's links 3 to 7, hand and fingers against the bench, the hotplate and the other arm. The beaker is not an obstacle (the fingers must go
around it); the contact monitor of the episode runner watches it.

The command is integrated from the previous COMMAND, not from the measured joints (a command only one step ahead of the measured joints makes
the position servo creep at a fraction of the planned speed). There is no sag correction yet (LATER; the simulator compensates gravity).

Contents:
    pad_rotation(approach, closing_hint, up_hint): the world rotation of a level pad frame for an approach direction.
    MinkArm: the solver for one arm.
"""

import mink
import mujoco
import numpy as np

from src.gripper_geometry import gripper_frame
from src.robot_helpers import arm_ids
from src.task_config import MINK_CFG


def pad_rotation(approach, closing_hint):
    """Gives the world rotation of a level pad frame: z along the approach, x the finger-closing axis, y = z cross x (vertical).

    Args:
        approach (array-like): The approach direction (3,); its horizontal part is used.
        closing_hint (array-like): A direction (3,) near the wanted closing axis; the closing axis is the horizontal direction perpendicular to the approach that is closest to
            it (the sign matters: it decides how the hand is rolled, so the hand's current closing axis keeps the roll of the home pose).

    Returns:
        numpy.ndarray: The 3 x 3 rotation matrix whose columns are the pad frame's x, y and z axes in the world.
    """
    z = np.array([approach[0], approach[1], 0.0], float)
    z /= np.linalg.norm(z)
    x = np.asarray(closing_hint, float) - z * float(np.dot(closing_hint, z))
    x[2] = 0.0
    x /= np.linalg.norm(x)
    return np.column_stack([x, np.cross(z, x), z])


class MinkArm:
    """The inverse kinematics of one arm for the scripted skills.

    Attributes:
        side (str): "left" or "right".
        q_cmd (numpy.ndarray): The arm's 7 commanded joint angles, radians; the starting point of the next step. Set by reset().
        pad_in_tcp (numpy.ndarray): The pad centre in the tool point frame, metres (3,).
        R_pad_in_tcp (numpy.ndarray): The pad frame's rotation in the tool point frame (columns: closing axis, y, approach axis).
    """

    def __init__(self, model, data, side, home_q, cfg=MINK_CFG, dt=1.0 / 150.0):
        """Builds the solver.

        Args:
            model (mujoco.MjModel): The compiled task model (with the bench, the hotplate and the other arm).
            data (mujoco.MjData): The simulation state; only used to read the gripper frame and to start the configuration.
            side (str): "left" or "right".
            home_q (array-like): The arm's home pose (7 radians): the target of the posture task.
            cfg (dict): MINK_CFG. Defaults to it.
            dt (float): The integration time of one step, seconds (the loop tick). Defaults to 1 / 150.
        """
        self.model, self.side, self.cfg, self.dt = model, side, cfg, dt
        ids = arm_ids(model, side)
        self.qadr, self.vadr = np.array(ids["qadr"]), np.array(ids["vadr"])
        gf = gripper_frame(model, side)
        self.pad_in_tcp = np.asarray(gf["pad_center_in_tcp"], float)
        self.R_pad_in_tcp = np.column_stack([gf["closing_axis"], np.cross(gf["approach_axis"], gf["closing_axis"]), gf["approach_axis"]])
        self.tcp = model.body(f"openarm_{side}_hand_tcp").id
        self.config = mink.Configuration(model, q=data.qpos.copy())
        self.frame = mink.FrameTask(f"openarm_{side}_hand_tcp", "body", position_cost=cfg["position_cost"], orientation_cost=cfg["orientation_cost"])
        cost = np.zeros(model.nv)
        cost[self.vadr] = cfg["posture_cost"]
        self.posture = mink.PostureTask(model, cost=cost)
        q_post = data.qpos.copy()
        q_post[self.qadr] = home_q
        self.posture.set_target(q_post)
        names = [model.joint(j).name for j in ids["jnt"]]
        joint_limit = mink.ConfigurationLimit(model)          # its margin would apply to every joint (the fingers' whole range is smaller than it): set the arm's own
        joint_limit.lower[:] = -mujoco.mjMAXVAL
        joint_limit.upper[:] = mujoco.mjMAXVAL
        rng = model.jnt_range[ids["jnt"]]
        joint_limit.lower[self.qadr] = rng[:, 0] + cfg["joint_margin_rad"]
        joint_limit.upper[self.qadr] = rng[:, 1] - cfg["joint_margin_rad"]
        limits = [joint_limit, mink.VelocityLimit(model, {n: cfg["max_joint_speed"] for n in names})]
        self.limits = limits + self._collision_limits(model, side, cfg)
        frozen = [d for d in range(model.nv) if d not in set(self.vadr.tolist())]
        self.freeze = mink.DofFreezingTask(model, dof_indices=frozen)
        self.q_cmd = np.asarray(home_q, float).copy()

    @staticmethod
    def _collision_limits(model, side, cfg):
        """Builds the collision avoidance limit: the arm's links 3 to 7, hand and fingers against the furniture and the other arm."""
        body = lambda g: model.body(int(model.geom_bodyid[g])).name
        col = [g for g in range(model.ngeom) if model.geom_contype[g] or model.geom_conaffinity[g]]
        other = "right" if side == "left" else "left"
        mine = [g for g in col if body(g).startswith(f"openarm_{side}_") and not body(g).endswith(("link0", "link1", "link2"))]
        furniture = [g for g in col if body(g) in ("bench", "task_hotplate")]
        theirs = [g for g in col if body(g).startswith(f"openarm_{other}_") and not body(g).endswith("link0")]
        out = []
        for pair, key in (((mine, furniture), "furniture"), ((mine, theirs), "right_arm")):
            if pair[0] and pair[1]:
                out.append(mink.CollisionAvoidanceLimit(model, [pair], gain=cfg["collision_gain"], minimum_distance_from_collisions=cfg["min_distance"][key],
                                                        collision_detection_distance=cfg["detect_distance"]))
        return out

    def reset(self, data):
        """Starts from the arm's measured joints: the command equals them."""
        self.q_cmd = data.qpos[self.qadr].copy()

    def pad_pose(self, data):
        """Gives the pad centre's pose from the joint angles in `data` (its kinematics must be current).

        Args:
            data (mujoco.MjData): The simulation state.

        Returns:
            tuple: (position (3,), rotation (3, 3)) of the pad frame in the world.
        """
        R = data.xmat[self.tcp].reshape(3, 3) @ self.R_pad_in_tcp
        return data.xpos[self.tcp] + data.xmat[self.tcp].reshape(3, 3) @ self.pad_in_tcp, R

    def step(self, data, position, rotation):
        """Moves the command one tick toward a pad pose.

        Args:
            data (mujoco.MjData): The simulation state (everything but the arm's joints is taken from it).
            position (array-like): The wanted pad centre in the world (3,), metres.
            rotation (array-like): The wanted pad frame rotation (3 x 3), see pad_rotation().

        Returns:
            numpy.ndarray: The new joint command (7,), radians (also kept in q_cmd).

        Raises:
            mink.NoSolutionFound: If the limits and the collision avoidance leave no solution.
        """
        q = data.qpos.copy()
        q[self.qadr] = self.q_cmd
        self.config.update(q)
        R_tcp = np.asarray(rotation, float) @ self.R_pad_in_tcp.T
        p_tcp = np.asarray(position, float) - R_tcp @ self.pad_in_tcp
        self.frame.set_target(mink.SE3.from_rotation_and_translation(mink.SO3.from_matrix(R_tcp), p_tcp))
        v = mink.solve_ik(self.config, [self.frame, self.posture], self.dt, self.cfg["solver"], damping=self.cfg["damping"], limits=self.limits, constraints=[self.freeze])
        self.q_cmd = self.q_cmd + v[self.vadr] * self.dt
        return self.q_cmd.copy()
